1→use serde::Serialize;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
#[serde(rename_all = "lowercase")]
pub enum Severity {
    Fail,
    Warn,
    Hint,
}
10→
#[derive(Debug, Clone, Serialize)]
pub struct Finding {
    pub severity: Severity,
    pub code: String,
    pub message: String,
    pub location: Option<String>,
}

#[derive(Debug, Clone, Serialize)]
20→pub struct Report {
    pub source: String,
    pub findings: Vec<Finding>,
}

impl Report {
    pub fn ok(&self) -> bool {
        !self.findings.iter().any(|f| f.severity == Severity::Fail)
    }

30→    pub fn fail(
        &mut self,
        code: impl Into<String>,
        message: impl Into<String>,
        location: impl Into<Option<String>>,
    ) {
        self.findings.push(Finding {
            severity: Severity::Fail,
            code: code.into(),
            message: message.into(),
40→            location: location.into(),
        });
    }

    pub fn warn(
        &mut self,
        code: impl Into<String>,
        message: impl Into<String>,
        location: impl Into<Option<String>>,
    ) {
50→        self.findings.push(Finding {
            severity: Severity::Warn,
            code: code.into(),
            message: message.into(),
            location: location.into(),
        });
    }

    pub fn hint(
        &mut self,
60→        code: impl Into<String>,
        message: impl Into<String>,
        location: impl Into<Option<String>>,
    ) {
        self.findings.push(Finding {
            severity: Severity::Hint,
            code: code.into(),
            message: message.into(),
            location: location.into(),
        });
70→    }

    pub fn to_markdown(&self) -> String {
        let status = if self.ok() { "PASS" } else { "FAIL" };
        let mut out = String::new();
        out.push_str(&format!(
            "# Plugin render-contract audit: {}\n\n",
            self.source
        ));
        out.push_str(&format!("**Status:** {status}\n\n"));
80→        if self.findings.is_empty() {
            out.push_str("No findings.\n");
            return out;
        }
        out.push_str("| Severity | Code | Location | Message |\n");
        out.push_str("|---|---|---|---|\n");
        for f in &self.findings {
            let sev = match f.severity {
                Severity::Fail => "FAIL",
                Severity::Warn => "WARN",
90→                Severity::Hint => "HINT",
            };
            let loc = f.location.as_deref().unwrap_or("—");
            let msg = f.message.replace('|', "\\|").replace('\n', " ");
            out.push_str(&format!("| {sev} | `{}` | `{loc}` | {msg} |\n", f.code));
        }
        out.push('\n');
        out
    }

100→    pub fn to_json(&self) -> anyhow::Result<String> {
        Ok(serde_json::to_string_pretty(self)?)
    }
}

1→//! Standalone subid taxonomy check (mirrors `op-plugins` oscal helpers).
//! Kept local so this crate builds without the zbus workspace patch.

use regex::Regex;
use std::sync::OnceLock;

const CATEGORIES: &[&str] = &["src", "prj", "sch", "mut", "obs", "evt", "exp"];

const COMPONENT_TYPES: &[&str] = &[
10→    "this-system",
    "system",
    "interconnection",
    "software",
    "hardware",
    "service",
    "policy",
    "physical",
    "process-procedure",
    "plan",
20→    "guidance",
    "standard",
    "validation",
    "network",
    // internal
    "agent",
    "container",
    "data",
    "privacy",
    "security",
30→    "storage",
    // aliases
    "ui",
    "llm",
    "agents",
];

pub fn validate_subid(subid: &str) -> Result<(), String> {
    static RE: OnceLock<Regex> = OnceLock::new();
    let re = RE.get_or_init(|| {
40→        let segment = r"[a-z0-9]+(?:-[a-z0-9]+)*";
        let pat = format!(
            r"^({})\.({})\.{segment}\.{segment}(?:\.{segment}){{0,2}}(?:@v[1-9][0-9]*)?$",
            CATEGORIES.join("|"),
            COMPONENT_TYPES.join("|"),
        );
        Regex::new(&pat).expect("subid regex")
    });
    if re.is_match(subid) {
        Ok(())
50→    } else {
        Err(format!("subid does not match required pattern: {subid}"))
    }
}

