1→//! Minimal render-contract-compliant plugin fixture for op-plugin-lint tests.
use serde::{Deserialize, Serialize};

/// Widget section.
#[derive(Debug, Clone, Serialize, Deserialize, Default, schemars::JsonSchema)]
#[schemars(extend("x-oscal-subid" = "sch.software.demo.widget.schema@v1"))]
pub struct Widget {
    /// Widget identifier.
    #[serde(default)]
10→    #[schemars(extend("x-oscal-subid" = "obs.software.demo.widget-id@v1"))]
    pub id: String,

    /// Listen port.
    #[serde(default)]
    #[schemars(
        range(min = 1, max = 65535),
        extend("x-oscal-subid" = "mut.software.demo.widget-port@v1")
    )]
