20→    out
}

fn walk(value: &Value, prefix: &str, out: &mut BTreeSet<String>) {
    match value {
        Value::Object(map) => {
            if !prefix.is_empty() {
                out.insert(prefix.to_string());
            }
            for (k, v) in map {
30→                let path = if prefix.is_empty() {
                    k.clone()
                } else {
                    format!("{prefix}.{k}")
                };
                out.insert(path.clone());
                walk(v, &path, out);
            }
        }
        Value::Array(items) => {
40→            if !prefix.is_empty() {
                out.insert(prefix.to_string());
            }
            let item_prefix = if prefix.is_empty() {
                "[*]".to_string()
