                format!("{prefix}[*]")
            };
            out.insert(item_prefix.clone());
            if let Some(first) = items.first() {
50→                walk(first, &item_prefix, out);
            }
        }
        _ => {
            if !prefix.is_empty() {
                out.insert(prefix.to_string());
            }
        }
    }
}
